const fs = require('fs');
const path = require('path');

const outDir = path.join(__dirname, 'public');
if (!fs.existsSync(outDir)) { fs.mkdirSync(outDir, { recursive: true }); }

fs.writeFileSync(path.join(outDir, 'icon-192-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'icon-512-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'icon-maskable-192-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'icon-maskable-512-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'apple-touch-icon-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'favicon-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'favicon-32x32-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'favicon-v2.svg'), "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"512\" height=\"512\">\n  <defs>\n    <linearGradient id=\"goldGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#F3E5AB\" />\n      <stop offset=\"30%\" stop-color=\"#D4AF37\" />\n      <stop offset=\"70%\" stop-color=\"#AA7A1E\" />\n      <stop offset=\"100%\" stop-color=\"#8C6214\" />\n    </linearGradient>\n    <linearGradient id=\"bgGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#1F1E22\" />\n      <stop offset=\"100%\" stop-color=\"#0E0D10\" />\n    </linearGradient>\n  </defs>\n  <rect width=\"512\" height=\"512\" rx=\"128\" fill=\"url(#bgGrad)\" />\n  <!-- Outer Gold Border -->\n  <rect x=\"24\" y=\"24\" width=\"464\" height=\"464\" rx=\"104\" fill=\"none\" stroke=\"url(#goldGrad)\" stroke-width=\"4\" opacity=\"0.6\" />\n  <!-- Stylized Shopping Bag & Luxury V Monogram -->\n  <path d=\"M192 192 V160 C192 124 220 96 256 96 C292 96 320 124 320 160 V192\" fill=\"none\" stroke=\"url(#goldGrad)\" stroke-width=\"20\" stroke-linecap=\"round\" />\n  <path d=\"M136 192 H376 L352 400 H160 Z\" fill=\"none\" stroke=\"url(#goldGrad)\" stroke-width=\"20\" stroke-linejoin=\"round\" />\n  <!-- Diamond Monogram V inside -->\n  <path d=\"M216 256 L256 344 L296 256\" fill=\"none\" stroke=\"url(#goldGrad)\" stroke-width=\"18\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n  <circle cx=\"256\" cy=\"236\" r=\"10\" fill=\"url(#goldGrad)\" />\n</svg>\n");
fs.writeFileSync(path.join(outDir, 'logo-v2.png'), Buffer.from('', 'base64'));
fs.writeFileSync(path.join(outDir, 'logo-v2.jpg'), Buffer.from('', 'base64'));
console.log('Icons v2 generated successfully.');
